// Shapes of the compiled content in content/. Generated by scripts/compile-lessons.ts from the vault.
// The lesson format itself is defined in the vault: Curriculum/Curriculum Spec.md §4.

export type Madhab = "hanafi" | "maliki" | "shafii" | "hanbali";

/** A learn screen whose text differs by school (Spec §4.3). `default` is always present. */
export type Variant = {
  default: string;
  hanafi?: string;
  maliki?: string;
  shafii?: string;
  hanbali?: string;
  /** Extra line shown only to converts under 18. */
  teen?: string;
  /** Bubbles that replace the screen's `bubbles` at a masjid of that school. */
  hanafi_bubbles?: string[];
  maliki_bubbles?: string[];
  shafii_bubbles?: string[];
  hanbali_bubbles?: string[];
};

export type Option = { text: string; correct?: boolean; best?: boolean; feedback?: string };

export type PhraseData = {
  arabic: string;
  translit: string;
  meaning: string;
  audio_id: string;
  when: string;
};

/** A body position the prayer figure can show (components/art/PrayerFigure.tsx). */
export type Pose =
  | "stand"
  | "takbir"
  | "qiyam"
  | "ruku"
  | "itidal"
  | "sujud"
  | "jalsa"
  | "tashahhud"
  | "salam-right"
  | "salam-left"
  | "dua";

/** One step of a how-to: short text, an optional picture id (see lib/content/pics.ts) and words to say. */
export type StepItem = { text: string; pic?: string; say?: string };

/** One movement in an animated prayer walkthrough. */
export type Move = { pose: Pose; text: string; say?: string };

/** Interactive Brilliant-style widgets (components/lesson/widgets.tsx). */
export type WidgetName =
  | "prayer-times"
  | "qibla"
  | "rakahs"
  | "fast-day"
  | "moon"
  | "tasbih"
  | "timeline"
  | "masjid-map"
  | "rows"
  | "zakat"
  | "iman-graph"
  | "letter";

/**
 * School overrides for any yaml screen: `variants: { hanafi: { steps: [...] } }` replaces those fields
 * for converts at a masjid of that school. Inline `{men}…{/men}`, `{women}…{/women}` and `{teen}…{/teen}`
 * tags work in every string and are resolved on the server (lib/content/render.ts).
 */
type Variants = {
  variants?: Partial<Record<Madhab, Record<string, unknown>>>;
  /** Shown only to that gender (hidden from the other; shown to everyone when gender is unknown). */
  audience?: "men" | "women";
  /** Shown only at a masjid of this school (e.g. a Hanafi-only du'a); hidden elsewhere. */
  school?: Madhab;
};

export type Screen = (
  | { n: number; type: "hook"; text: string; pic?: string }
  | { n: number; type: "takeaway"; text: string; pic?: string }
  | { n: number; type: "closing"; text: string }
  | { n: number; type: "learn"; text?: string; variant?: Variant; visual?: string; pic?: string; bubbles?: string[] }
  | {
      n: number;
      type: "choice";
      prompt: string;
      options: Option[];
      pic?: string;
      /** A clip to play with the question ("tap the letter you hear"): a path under public/, e.g. /audio/alphabet/02-baa.wav. */
      audio?: string;
    }
  | { n: number; type: "multi"; prompt: string; options: Option[] }
  | { n: number; type: "scenario"; situation: string; options: Option[]; pic?: string }
  | { n: number; type: "order"; prompt: string; items: string[]; feedback?: string; pics?: string[] }
  | { n: number; type: "match"; prompt: string; pairs: { left: string; right: string }[] }
  | { n: number; type: "reveal"; title?: string; cards: { front: string; back: string; pic?: string; /** Front is Arabic. */ rtl?: boolean; /** Arabic shown in the Arabic font above the back. */ arabic?: string }[] }
  | ({ n: number; type: "phrase" } & PhraseData)
  | {
      n: number;
      type: "practice";
      title: string;
      steps: string[];
      optional?: boolean;
      done_text?: string;
      carry_forward?: boolean;
    }
  | {
      n: number;
      type: "reflect";
      prompt: string;
      share_with_mentor?: string | boolean;
      resurface?: string[];
      resurface_after_days?: number;
    }
  | { n: number; type: "ask_ai"; chips: string[] }
  | {
      n: number;
      type: "roleplay";
      character: string;
      setup: string;
      goal: string;
      success_looks_like: string;
      coach_notes: string;
    }
  | { n: number; type: "do_today"; text: string; log?: string; optional_extra?: string; steps?: string[]; pic?: string }
  | { n: number; type: "steps"; title: string; intro?: string; steps: StepItem[]; done_text?: string }
  | { n: number; type: "prayer"; title: string; intro?: string; moves: Move[]; done_text?: string }
  | { n: number; type: "tap_words"; prompt: string; answer: string; extra: string[]; feedback?: string }
  | {
      n: number;
      type: "sort";
      prompt: string;
      buckets: [string, string];
      items: { text: string; bucket: 0 | 1; why?: string }[];
    }
  | { n: number; type: "fill"; before: string; after?: string; options: Option[]; /** The sentence and options are Arabic. */ dir?: "rtl" }
  | {
      n: number;
      type: "quiz";
      title: string;
      intro?: string;
      /** How many questions (default 6). */
      count?: number;
      /** Lessons to draw from first (e.g. the prayer days), if the convert has done them. */
      prefer?: string[];
      /** Filled in on the server from the Check questions of lessons this convert has finished. */
      items?: QuizItem[];
    }
  | {
      n: number;
      type: "widget";
      widget: WidgetName;
      prompt?: string;
      text?: string;
      /** Widget-specific: tasbih `phrases`, timeline `events`, masjid-map `areas`, zakat `nisab`, iman-graph `points`, letter `letters`. */
      phrases?: { translit: string; meaning?: string; arabic?: string; count: number }[];
      events?: { when: string; title: string; text: string; pic?: string }[];
      areas?: Record<string, string>;
      nisab?: number;
      points?: { label: string; text: string }[];
      /** letter: the Arabic letters to meet, in order (lib/content/alphabet.ts). */
      letters?: string[];
    }
) &
  Variants;

export type ScreenType = Screen["type"];

/** One welcome-back quiz question, taken from a finished lesson's Check. */
export type QuizItem = { lessonId: string; lessonTitle: string; day: number | null; prompt: string; options: Option[] };

export type CheckItem = { prompt: string; options: Option[] };

export type Lesson = {
  id: string; // "day-03", "ramadan-1", "alphabet-01"
  /** "track": an optional Practice track lesson (alphabet, seerah), outside the 90-day path. */
  kind: "day" | "module" | "track";
  day: number | null;
  module: string | null;
  track: string | null;
  /** Position within its track (1-based); null for days and modules. */
  order: number | null;
  phase: number | null;
  unit: number | null;
  title: string;
  hook: string;
  minutes: number;
  skills: string[];
  painPoints: string[];
  logs: string[];
  madhabSensitive: boolean;
  scholarFlags: string[];
  status: string;
  glossary: string[];
  screens: Screen[];
  prayerPhrase: PhraseData | null;
  check: CheckItem[];
  /** True when any text has {men}/{women} tags: the app needs the convert's gender to render it. */
  usesGender: boolean;
  /** For the AI guide only. Never shown to the convert. */
  aiContext: string;
  madhabNote: string | null;
  sourcesMd: string;
  /** Citation keys ("Q 1:2", "Abu Dawud 832") used anywhere in what the convert sees. */
  citations: string[];
  /** Hash of the source markdown: records exactly which text a convert saw. */
  contentVersion: string;
};

export type LessonSummary = Pick<
  Lesson,
  "id" | "kind" | "day" | "module" | "track" | "order" | "phase" | "unit" | "title" | "hook" | "minutes" | "status" | "logs"
>;

export type Unit = { n: number; phase: number; title: string; firstDay: number; lastDay: number };

export type ContentIndex = {
  lessons: LessonSummary[];
  units: Unit[];
  /** Lessons per optional Practice track (the unbroken run from 01; lib/content/track-counts.ts). */
  tracks: Record<string, number>;
  compiledAt: string;
};

export type Citation = {
  key: string; // "Q 2:186" | "Q 31:14–15" | "Bukhari 50"
  kind: "quran" | "hadith";
  /** Our own paraphrase (hadith only). Never shown in quotation marks. */
  gist?: string;
  grade?: string;
  /** Full English text from the source dataset (Saheeh International / sunnah.com translations). */
  english: string;
  arabic: string;
  url: string;
};

export type GlossaryEntry = { term: string; arabic: string; meaning: string; firstTaught: string };
